action.command:
cd /workspace/app && cat > /tmp/scan7.mjs <<'EOF'
import fs from "fs";
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const lines = s.split("\n");
// Find default numeric values for minimumReleaseAge and fetch-retry/timeout
for (let n=0;n<lines.length;n++){
  const m = lines[n];
  if (/minimumReleaseAge/.test(m) && /\b(1440|2880|4320|720|10080|43200)\b/.test(m)) console.log("MRAGE:", n, m.trim().slice(0,140));
  if (/fetchTimeout|retryMaxTimeout|networkTimeout|fetchRetries/.test(m) && /:\s*\d+/.test(m)) console.log("NET:", n, m.trim().slice(0,120));
}
EOF
node /tmp/scan7.mjs | head -40

